package ma.translogix.model;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;

/**
 * One payroll record of one employee for one month. Salaries are entered by the accountant:
 * the application never invents a base salary, it only computes the net from real inputs.
 */
public class Paie {
    private Long id;
    /** PAI-YYYYMM-NNN, generated by PaieService. */
    private String numero;
    private Long employeId;
    private YearMonth periode;
    private BigDecimal salaireBase;
    private BigDecimal primes;
    private BigDecimal deductions;
    /** salaireBase + primes - deductions, computed and stored by PaieService. */
    private BigDecimal net;
    private LocalDate datePaiement;
    private ModePaiementSalaire modePaiement;
    private String reference;
    private StatutPaie statut = StatutPaie.EN_ATTENTE;

    public Paie() {
    }

    public Paie(Long id, String numero, Long employeId, YearMonth periode, BigDecimal salaireBase,
                BigDecimal primes, BigDecimal deductions, BigDecimal net, LocalDate datePaiement,
                ModePaiementSalaire modePaiement, String reference, StatutPaie statut) {
        this.id = id;
        this.numero = numero;
        this.employeId = employeId;
        this.periode = periode;
        this.salaireBase = salaireBase;
        this.primes = primes;
        this.deductions = deductions;
        this.net = net;
        this.datePaiement = datePaiement;
        this.modePaiement = modePaiement;
        this.reference = reference;
        this.statut = statut;
    }

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }

    public String getNumero() { return numero; }
    public void setNumero(String numero) { this.numero = numero; }

    public Long getEmployeId() { return employeId; }
    public void setEmployeId(Long employeId) { this.employeId = employeId; }

    public YearMonth getPeriode() { return periode; }
    public void setPeriode(YearMonth periode) { this.periode = periode; }

    public BigDecimal getSalaireBase() { return salaireBase; }
    public void setSalaireBase(BigDecimal salaireBase) { this.salaireBase = salaireBase; }

    public BigDecimal getPrimes() { return primes; }
    public void setPrimes(BigDecimal primes) { this.primes = primes; }

    public BigDecimal getDeductions() { return deductions; }
    public void setDeductions(BigDecimal deductions) { this.deductions = deductions; }

    public BigDecimal getNet() { return net; }
    public void setNet(BigDecimal net) { this.net = net; }

    public LocalDate getDatePaiement() { return datePaiement; }
    public void setDatePaiement(LocalDate datePaiement) { this.datePaiement = datePaiement; }

    public ModePaiementSalaire getModePaiement() { return modePaiement; }
    public void setModePaiement(ModePaiementSalaire modePaiement) { this.modePaiement = modePaiement; }

    public String getReference() { return reference; }
    public void setReference(String reference) { this.reference = reference; }

    public StatutPaie getStatut() { return statut; }
    public void setStatut(StatutPaie statut) { this.statut = statut; }
}
